//! Currency code rendering.
//!
//! `ProductCurrency` is generated by sea-orm and renamed to snake_case, so it
//! serializes as `"ngn"`. Clients expect ISO 4217 codes, so responses are
//! emitted uppercased (`"NGN"`) instead of patching the generated enum.

use std::fmt;

use serde::Serializer;

use crate::models::sea_orm_active_enums::ProductCurrency;

impl fmt::Display for ProductCurrency {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let code = match self {
            Self::Ngn => "ngn",
            Self::Usd => "usd",
            Self::Gbp => "gbp",
            Self::Eur => "eur",
            Self::Ghs => "ghs",
            Self::Kes => "kes",
            Self::Zar => "zar",
            Self::Cad => "cad",
            Self::Aud => "aud",
            Self::Jpy => "jpy",
            Self::Cny => "cny",
            Self::Inr => "inr",
            Self::Aed => "aed",
            Self::Xof => "xof",
        };

        f.write_str(code)
    }
}

pub fn serialize_currency<S>(currency: &ProductCurrency, serializer: S) -> Result<S::Ok, S::Error>
where
    S: Serializer,
{
    serializer.serialize_str(&currency.to_string().to_uppercase())
}

/// Parses a client supplied currency code.
///
/// Responses emit ISO 4217 codes (`NGN`); accept any casing and surrounding
/// whitespace on the way in.
pub fn parse_currency(raw: &str) -> Option<ProductCurrency> {
    ProductCurrency::try_from(raw.trim().to_lowercase().as_str()).ok()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde::Serialize;

    #[derive(Serialize)]
    struct CurrencyOut {
        #[serde(serialize_with = "super::serialize_currency")]
        currency: ProductCurrency,
    }

    fn emit(currency: ProductCurrency) -> serde_json::Value {
        serde_json::to_value(CurrencyOut { currency }).unwrap()
    }

    #[test]
    fn serializes_as_uppercase_iso_code() {
        assert_eq!(
            emit(ProductCurrency::Ngn)["currency"],
            serde_json::json!("NGN")
        );
        assert_eq!(
            emit(ProductCurrency::Usd)["currency"],
            serde_json::json!("USD")
        );
        assert_eq!(
            emit(ProductCurrency::Gbp)["currency"],
            serde_json::json!("GBP")
        );
        assert_eq!(
            emit(ProductCurrency::Xof)["currency"],
            serde_json::json!("XOF")
        );
    }

    #[test]
    fn currency_is_serialized_as_json_string_not_number() {
        let value = emit(ProductCurrency::Ghs);

        assert!(value["currency"].is_string());
    }

    #[test]
    fn every_variant_renders_a_three_letter_uppercase_code() {
        for currency in [
            ProductCurrency::Ngn,
            ProductCurrency::Usd,
            ProductCurrency::Gbp,
            ProductCurrency::Eur,
            ProductCurrency::Ghs,
            ProductCurrency::Kes,
            ProductCurrency::Zar,
            ProductCurrency::Cad,
            ProductCurrency::Aud,
            ProductCurrency::Jpy,
            ProductCurrency::Cny,
            ProductCurrency::Inr,
            ProductCurrency::Aed,
            ProductCurrency::Xof,
        ] {
            let rendered = currency.to_string().to_uppercase();

            assert_eq!(rendered.len(), 3, "{rendered} is not a three letter code");
            assert!(
                rendered.chars().all(|c| c.is_ascii_uppercase()),
                "{rendered} is not uppercase"
            );
        }
    }

    #[test]
    fn display_matches_the_generated_serde_representation() {
        assert_eq!(
            ProductCurrency::Ngn.to_string(),
            serde_json::to_value(ProductCurrency::Ngn)
                .unwrap()
                .as_str()
                .unwrap()
        );
    }

    #[test]
    fn parses_currency_regardless_of_casing_or_padding() {
        for raw in ["ngn", "NGN", "Ngn", "  ngn  ", "Ngn\n"] {
            assert_eq!(
                parse_currency(raw),
                Some(ProductCurrency::Ngn),
                "{raw:?} should parse as NGN"
            );
        }
    }

    #[test]
    fn rejects_unknown_and_empty_currency_codes() {
        for raw in ["", "   ", "xyz", "naira", "ngnn", "n"] {
            assert_eq!(parse_currency(raw), None, "{raw:?} should be rejected");
        }
    }

    #[test]
    fn parses_every_supported_currency() {
        for (raw, expected) in [
            ("usd", ProductCurrency::Usd),
            ("gbp", ProductCurrency::Gbp),
            ("eur", ProductCurrency::Eur),
            ("ghs", ProductCurrency::Ghs),
            ("kes", ProductCurrency::Kes),
            ("zar", ProductCurrency::Zar),
            ("cad", ProductCurrency::Cad),
            ("aud", ProductCurrency::Aud),
            ("jpy", ProductCurrency::Jpy),
            ("cny", ProductCurrency::Cny),
            ("inr", ProductCurrency::Inr),
            ("aed", ProductCurrency::Aed),
            ("xof", ProductCurrency::Xof),
        ] {
            assert_eq!(parse_currency(raw), Some(expected));
        }
    }
}
